import { StringPalette } from "../../../Util/StringPalette";
export class BinarySchemaNode {
    data;
    get name() {
        return this.data.name;
    }
    valuePalette;
    bitIndex = 0;
    bitMask = 0;
    constructor(data) {
        this.data = data;
        this.bitIndex = data.bitIndex;
        this.bitMask = (1 << data.bitSize) - 1;
        if (data.values)
            this.valuePalette = new StringPalette(data.values);
    }
    getValue(data) {
        return (data & (this.bitMask << this.bitIndex)) >> this.bitIndex;
    }
    setValue(data, value) {
        return ((data & ~(this.bitMask << this.bitIndex)) |
            ((value & this.bitMask) << this.bitIndex));
    }
}
